import java.util.Properties

plugins {
    id("com.android.library") version "8.9.2" apply false
    id("com.android.application") version "8.9.2" apply false
    id("org.jetbrains.kotlin.android") version "2.1.20" apply false
}

// Generated by the registered client-track version sync; CI checks for drift.
val releaseProperties = Properties().apply {
    file("release-version.properties").inputStream().use { load(it) }
}
val releaseVersion = releaseProperties.getProperty("version")
    ?: error("Missing synchronized client release version")
allprojects { version = releaseVersion }
